DROP TABLE IF EXISTS approvals;
DROP TABLE IF EXISTS reviews;
DROP TABLE IF EXISTS recommendation_history;
DROP TABLE IF EXISTS club_assignments;
DROP TABLE IF EXISTS applications;
DROP TABLE IF EXISTS audit_logs;
DROP TABLE IF EXISTS users;
CREATE TABLE users (id TEXT PRIMARY KEY NOT NULL,auth_user_id TEXT NOT NULL UNIQUE,alias TEXT NOT NULL UNIQUE,recovery_hash TEXT NOT NULL UNIQUE,role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student','club_manager','admin')),is_active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,last_active_at INTEGER NOT NULL);
CREATE TABLE clubs (id TEXT PRIMARY KEY NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL,field TEXT,club_type TEXT,description TEXT NOT NULL,activity_details TEXT NOT NULL,teacher_display_text TEXT,contact_location TEXT,activity_location TEXT,capacity INTEGER NOT NULL DEFAULT 20,recruitment_status TEXT NOT NULL DEFAULT 'open',application_start_at INTEGER,application_end_at INTEGER,manager_user_id TEXT,is_active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(manager_user_id) REFERENCES users(id));
CREATE TABLE applications (id TEXT PRIMARY KEY NOT NULL,public_id TEXT NOT NULL UNIQUE,user_id TEXT NOT NULL,club_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'submitted',motivation TEXT NOT NULL,career_interest TEXT NOT NULL,experience TEXT NOT NULL,additional_answer TEXT,submitted_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,cancelled_at INTEGER,reviewed_at INTEGER,reviewed_by TEXT,review_comment TEXT,google_sheet_synced INTEGER NOT NULL DEFAULT 0,google_sheet_synced_at INTEGER,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(reviewed_by) REFERENCES users(id),UNIQUE(user_id,club_id));
CREATE TABLE posts (id TEXT PRIMARY KEY NOT NULL,author_user_id TEXT NOT NULL,author_alias TEXT NOT NULL,category TEXT NOT NULL,club_id TEXT,title TEXT NOT NULL,content TEXT NOT NULL,is_notice INTEGER NOT NULL DEFAULT 0,is_hidden INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,deleted_at INTEGER,FOREIGN KEY(author_user_id) REFERENCES users(id));
CREATE TABLE post_comments (id TEXT PRIMARY KEY NOT NULL,post_id TEXT NOT NULL,author_user_id TEXT NOT NULL,author_alias TEXT NOT NULL,content TEXT NOT NULL,is_hidden INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,deleted_at INTEGER,FOREIGN KEY(post_id) REFERENCES posts(id),FOREIGN KEY(author_user_id) REFERENCES users(id));
CREATE TABLE questions (id TEXT PRIMARY KEY NOT NULL,author_user_id TEXT NOT NULL,author_alias TEXT NOT NULL,club_id TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,is_private INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'waiting',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,deleted_at INTEGER,FOREIGN KEY(author_user_id) REFERENCES users(id));
CREATE TABLE answers (id TEXT PRIMARY KEY NOT NULL,question_id TEXT NOT NULL,author_user_id TEXT NOT NULL,author_role TEXT NOT NULL,content TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,deleted_at INTEGER,FOREIGN KEY(question_id) REFERENCES questions(id),FOREIGN KEY(author_user_id) REFERENCES users(id));
CREATE TABLE audit_logs (id TEXT PRIMARY KEY NOT NULL,actor_user_id TEXT,actor_role TEXT NOT NULL,action_type TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,before_data TEXT,after_data TEXT,created_at INTEGER NOT NULL,FOREIGN KEY(actor_user_id) REFERENCES users(id));
CREATE TABLE sync_jobs (id TEXT PRIMARY KEY NOT NULL,data_type TEXT NOT NULL,source_id TEXT NOT NULL,operation TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',retry_count INTEGER NOT NULL DEFAULT 0,last_error TEXT,resolved_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(data_type,source_id,operation));
CREATE INDEX applications_user_idx ON applications(user_id);
CREATE INDEX applications_club_idx ON applications(club_id);
CREATE INDEX posts_created_idx ON posts(created_at);
CREATE INDEX questions_club_idx ON questions(club_id);
